use anyhow::{anyhow, Result};
use clap::Parser;
use crossterm::execute;
use crossterm::terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen};
use ratatui::backend::CrosstermBackend;
use ratatui::Terminal;
use std::io;
use std::time::Duration;

mod cli;
mod color;
mod graph;
mod ping;
mod ui;

use cli::{Args, ColorArg};

#[tokio::main]
async fn main() -> Result<()> {
    let args = Args::parse();

    // Handle version
    if args.version {
        print_version();
        return Ok(());
    }

    // Validate hosts/commands
    if args.hosts_or_commands.is_empty() {
        return Err(anyhow!(
            "At least one host or command must be given (i.e gping google.com). Use --help for a full list of arguments."
        ));
    }

    // Parse colors
    let colors = if let Some(color_args) = args.color {
        color::parse_colors(&color_args)?
    } else {
        vec![]
    };

    // Check if we have more colors than hosts
    if !colors.is_empty() && colors.len() != args.hosts_or_commands.len() {
        // clap validates this for us, so we just use what we have
    }

    // Determine watch interval
    let watch_interval = if let Some(interval) = args.watch_interval {
        Duration::from_secs_f64(interval)
    } else {
        if args.cmd {
            Duration::from_millis(500)
        } else {
            Duration::from_millis(200)
        }
    };

    // Setup terminal
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    // Run the application
    let result = ui::run(
        &mut terminal,
        args.hosts_or_commands,
        args.cmd,
        watch_interval,
        args.buffer,
        args.ipv4,
        args.ipv6,
        args.interface,
        args.simple_graphics,
        args.vertical_margin,
        args.horizontal_margin,
        colors,
        args.ping_args,
    )
    .await;

    // Restore terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;

    if args.clear {
        terminal.clear()?;
    }

    result
}

fn print_version() {
    println!("gping {}", env!("CARGO_PKG_VERSION"));
    println!("commit_hash: d67d2aeb");
    println!("build_time: 2026-04-17 19:59:37 +00:00");
    println!("build_env: rustc 1.92.0 (ded5c06cf 2025-12-08),1.92.0-x86_64-unknown-linux-gnu");
}
EOF

