use anyhow::{anyhow, Result};
use ratatui::style::Color;

#[derive(Clone, Debug)]
pub struct ColorPair {
    pub r: u8,
    pub g: u8,
    pub b: u8,
}

impl ColorPair {
    pub fn to_ratatui_color(&self) -> Color {
        Color::Rgb(self.r, self.g, self.b)
    }
}

pub fn parse_colors(color_args: &[String]) -> Result<Vec<ColorPair>> {
    let mut colors = Vec::new();

    for color_str in color_args {
        for color_name in color_str.split(',') {
            let color_name = color_name.trim();
            if color_name.is_empty() {
                continue;
            }

            let color = parse_single_color(color_name)?;
            colors.push(color);
        }
    }

    Ok(colors)
}

fn parse_single_color(color: &str) -> Result<ColorPair> {
    // Try hex color first
    if color.starts_with('#') {
        if color.len() == 7 {
            let r = u8::from_str_radix(&color[1..3], 16)
                .map_err(|_| anyhow!("Invalid color code: `{}`", color))?;
            let g = u8::from_str_radix(&color[3..5], 16)
                .map_err(|_| anyhow!("Invalid color code: `{}`", color))?;
            let b = u8::from_str_radix(&color[5..7], 16)
                .map_err(|_| anyhow!("Invalid color code: `{}`", color))?;
            return Ok(ColorPair { r, g, b });
        } else {
            return Err(anyhow!("Invalid color code: `{}`", color));
        }
    }

    // Try named colors
    let (r, g, b) = match color.to_lowercase().as_str() {
        "black" => (0, 0, 0),
        "red" => (255, 0, 0),
        "green" => (0, 255, 0),
        "yellow" => (255, 255, 0),
        "blue" => (0, 0, 255),
        "magenta" => (255, 0, 255),
        "cyan" => (0, 255, 255),
        "gray" => (128, 128, 128),
        "dark-gray" => (64, 64, 64),
        "light-red" => (255, 128, 128),
        "light-green" => (128, 255, 128),
        "light-yellow" => (255, 255, 128),
        "light-blue" => (128, 128, 255),
        "light-magenta" => (255, 128, 255),
        "light-cyan" => (128, 255, 255),
        "white" => (255, 255, 255),
        _ => return Err(anyhow!("Invalid color code: `{}`", color)),
    };

    Ok(ColorPair { r, g, b })
}
EOF

