use anyhow::{anyhow, Result};
use std::process::Stdio;
use tokio::io::AsyncBufReadExt;
use tokio::process::Command;

pub struct PingResult {
    pub time: f64,
}

pub async fn ping_host(
    host: &str,
    ipv4: bool,
    ipv6: bool,
    interface: Option<&str>,
    ping_args: Option<&[String]>,
) -> Result<PingResult> {
    let mut cmd = Command::new("ping");

    if ipv4 {
        cmd.arg("-4");
    } else if ipv6 {
        cmd.arg("-6");
    }

    if let Some(iface) = interface {
        cmd.arg("-I").arg(iface);
    }

    cmd.arg("-c").arg("1");
    cmd.arg("-W").arg("2");

    if let Some(extra_args) = ping_args {
        for arg in extra_args {
            cmd.arg(arg);
        }
    }

    cmd.arg(host);
    cmd.stdout(Stdio::piped());
    cmd.stderr(Stdio::piped());

    let mut child = cmd.spawn()
        .map_err(|e| anyhow!("Error spawning ping: {}", e))?;

    let stdout = child.stdout.take()
        .ok_or_else(|| anyhow!("Failed to open stdout"))?;

    let reader = tokio::io::BufReader::new(stdout);
    let mut lines = reader.lines();

    let mut time = 0.0;
    while let Some(line) = lines.next_line().await? {
        // Look for the time= pattern in ping output
        if let Some(start) = line.find("time=") {
            let rest = &line[start + 5..];
            if let Some(space_pos) = rest.find(|c: char| c.is_whitespace()) {
                let time_str = &rest[..space_pos];
                time = time_str.parse::<f64>()
                    .unwrap_or(0.0);
                break;
            }
        }
    }

    let status = child.wait().await?;

    if !status.success() {
        return Err(anyhow!("Ping failed"));
    }

    Ok(PingResult { time })
}

pub async fn run_command(cmd_str: &str) -> Result<f64> {
    let start = std::time::Instant::now();

    let output = if cfg!(target_os = "windows") {
        Command::new("cmd")
            .args(&["/C", cmd_str])
            .output()
            .await?
    } else {
        Command::new("sh")
            .arg("-c")
            .arg(cmd_str)
            .output()
            .await?
    };

    let elapsed = start.elapsed().as_secs_f64() * 1000.0; // Convert to ms

    if output.status.success() {
        Ok(elapsed)
    } else {
        Err(anyhow!("Command failed"))
    }
}
