    hosts_or_commands: Vec<String>,
    cmd_mode: bool,
    watch_interval: Duration,
    buffer_seconds: u64,
    ipv4: bool,
    ipv6: bool,
    interface: Option<String>,
    simple_graphics: bool,
    vertical_margin: u16,
    horizontal_margin: u16,
    colors: Vec<ColorPair>,
    ping_args: Option<Vec<String>>,
) -> Result<()> {
    let mut graphs: Vec<GraphData> = hosts_or_commands
        .iter()
        .map(|_| GraphData::new((buffer_seconds as usize) * 5))
        .collect();

    loop {
        // Check for key press
        if event::poll(Duration::from_millis(10))? {
            if let Event::Key(key) = event::read()? {
                if key.code == KeyCode::Char('c') && key.modifiers.contains(event::KeyModifiers::CONTROL) {
                    break;
                } else if key.code == KeyCode::Esc || key.code == KeyCode::Char('q') {
                    break;
                }
            }
        }

        // Fetch ping/command data
        for (idx, host_or_cmd) in hosts_or_commands.iter().enumerate() {
            let result = if cmd_mode {
                match ping::run_command(host_or_cmd).await {
                    Ok(time) => time,
                    Err(_) => continue,
                }
            } else {
                match ping::ping_host(
                    host_or_cmd,
                    ipv4,
                    ipv6,
                    interface.as_deref(),
                    ping_args.as_deref(),
                )
                .await
                {
                    Ok(ping_result) => ping_result.time,
                    Err(_) => continue,
                }
            };

            graphs[idx].push(result);
        }

        // Draw UI
        terminal.draw(|frame| {
            let area = frame.area();
            // Simple placeholder for now
        })?;

        tokio::time::sleep(watch_interval).await;
    }

    Ok(())
}
