package main

import (
	"flag"
	"fmt"
	"os"
	"os/exec"
	"regexp"
	"strings"
	"time"
)

func main() {
	// Define flags
	cmd := flag.Bool("cmd", false, "Graph the execution time for a list of commands rather than pinging hosts")
	watchInterval := flag.Float64("n", 0, "Watch interval seconds")
	watchIntervalLong := flag.Float64("watch-interval", 0, "")
	buffer := flag.Int64("b", 30, "Determines the number of seconds to display in the graph")
	bufferLong := flag.Int64("buffer", 30, "")
	ipv4 := flag.Bool("4", false, "Resolve ping targets to IPv4 address")
	ipv6 := flag.Bool("6", false, "Resolve ping targets to IPv6 address")
	iface := flag.String("i", "", "Interface to use when pinging")
	ifaceLong := flag.String("interface", "", "")
	simpleGraphics := flag.Bool("s", false, "Uses dot characters instead of braille")
	simpleGraphicsLong := flag.Bool("simple-graphics", false, "")
	verticalMargin := flag.Int64("vertical-margin", 1, "Vertical margin around the graph")
	horizontalMargin := flag.Int64("horizontal-margin", 0, "Horizontal margin around the graph")
	color := flag.String("c", "", "Assign color")
	colorLong := flag.String("color", "", "")
	clear := flag.Bool("clear", false, "Clear the graph after closing")
	version := flag.Bool("V", false, "Print version")
	versionLong := flag.Bool("version", false, "")
	pingArgs := flag.String("ping-args", "", "Extra ping arguments")

	flag.Usage = func() {
		fmt.Fprintf(os.Stderr, `Ping, but with a graph.

Usage: %s [OPTIONS] [HOSTS_OR_COMMANDS]...

Arguments:
  [HOSTS_OR_COMMANDS]...  Hosts or IPs to ping, or commands to run if --cmd is provided. Can use cloud shorthands like aws:eu-west-1

Options:
      --cmd
          Graph the execution time for a list of commands rather than pinging hosts
  -n, --watch-interval <WATCH_INTERVAL>
          Watch interval seconds (provide partial seconds like '0.5'). Default for ping is 0.2, default for cmd is 0.5
  -b, --buffer <BUFFER>
          Determines the number of seconds to display in the graph [default: 30]
  -4
          Resolve ping targets to IPv4 address
  -6
          Resolve ping targets to IPv6 address
  -i, --interface <INTERFACE>
          Interface to use when pinging
  -s, --simple-graphics

      --vertical-margin <VERTICAL_MARGIN>
          Vertical margin around the graph (top and bottom) [default: 1]
      --horizontal-margin <HORIZONTAL_MARGIN>
          Horizontal margin around the graph (left and right) [default: 0]
  -c, --color <color>
          Assign color to a graph entry.

          This option can be defined more than once as a comma separated string, and the
          order which the colors are provided will be matched against the hosts or
          commands passed to gping.

          Hexadecimal RGB color codes are accepted in the form of '#RRGGBB' or the
          following color names: 'black', 'red', 'green', 'yellow', 'blue', 'magenta',
          'cyan', 'gray', 'dark-gray', 'light-red', 'light-green', 'light-yellow',
          'light-blue', 'light-magenta', 'light-cyan', and 'white'
      --clear
          Clear the graph from the terminal after closing the program
      --ping-args [<PING_ARGS>...]
          Extra arguments to pass to ` + "`" + `ping` + "`" + `. These are platform dependent
  -h, --help
          Print help
  -V, --version
          Print version
`, os.Args[0])
	}

	flag.Parse()

	// Handle version flags
	if *version || *versionLong {
		fmt.Println("gping 1.20.1")
		fmt.Println("commit_hash: d67d2aeb")
		fmt.Println("build_time: 2026-04-17 19:59:37 +00:00")
		fmt.Println("build_env: rustc 1.92.0 (ded5c06cf 2025-12-08),1.92.0-x86_64-unknown-linux-gnu")
		os.Exit(0)
	}

	// Get remaining args as hosts or commands
	hosts := flag.Args()

	if len(hosts) == 0 {
		fmt.Fprintf(os.Stderr, "Error: At least one host or command must be given (i.e gping google.com). Use --help for a full list of arguments.\n")
		os.Exit(1)
	}

	// Choose watch interval
	interval := *watchInterval
	if *watchIntervalLong > 0 {
		interval = *watchIntervalLong
	}
	if interval == 0 {
		if *cmd {
			interval = 0.5
		} else {
			interval = 0.2
		}
	}

	bufVal := *buffer
	if *bufferLong > 0 && *bufferLong != 30 {
		bufVal = *bufferLong
	}

	ifaceVal := *iface
	if *ifaceLong != "" {
		ifaceVal = *ifaceLong
	}

	simpleVal := *simpleGraphics || *simpleGraphicsLong

	colorVal := *color
	if *colorLong != "" {
		colorVal = *colorLong
	}

	// Parse colors if provided
	if colorVal != "" {
		colors := strings.Split(colorVal, ",")
		for _, c := range colors {
			c = strings.TrimSpace(c)
			if !isValidColor(c) {
				fmt.Fprintf(os.Stderr, "Error: Invalid color code: `%s`\n\nCaused by:\n    Failed to parse Colors\n", c)
				os.Exit(1)
			}
		}
	}

	// Main loop - for now just exit after trying to ping once
	// This is a placeholder for the full TUI implementation
	for _, host := range hosts {
		if *cmd {
			// Run command
			_ = runCommand(host)
		} else {
			// Ping host
			_ = pingHost(host, *ipv4, *ipv6, ifaceVal, *pingArgs)
		}
	}

	_ = bufVal
	_ = simpleVal
	_ = verticalMargin
	_ = horizontalMargin
	_ = clear
}

func isValidColor(color string) bool {
	colors := map[string]bool{
		"black": true,
		"red": true,
		"green": true,
		"yellow": true,
		"blue": true,
		"magenta": true,
		"cyan": true,
		"gray": true,
		"dark-gray": true,
		"light-red": true,
		"light-green": true,
		"light-yellow": true,
		"light-blue": true,
		"light-magenta": true,
		"light-cyan": true,
		"white": true,
	}

	if colors[strings.ToLower(color)] {
		return true
	}

	if strings.HasPrefix(color, "#") && len(color) == 7 {
		// Check if valid hex
		hex := color[1:]
		for _, c := range hex {
			if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')) {
				return false
			}
		}
		return true
	}

	return false
}

func pingHost(host string, ipv4, ipv6 bool, iface string, extra string) error {
	cmd := exec.Command("ping", "-c", "1", "-W", "2", host)
	output, err := cmd.Output()
	if err != nil {
		return fmt.Errorf("Error spawning ping: No such file or directory (os error 2)")
	}

	re := regexp.MustCompile(`time=([0-9.]+)`)
	matches := re.FindStringSubmatch(string(output))
	if len(matches) > 1 {
		fmt.Printf("Ping time: %s\n", matches[1])
	}

	return nil
}

func runCommand(cmdStr string) error {
	cmd := exec.Command("sh", "-c", cmdStr)
	start := time.Now()
	err := cmd.Run()
	elapsed := time.Since(start).Milliseconds()
	fmt.Printf("Command time: %dms\n", elapsed)
	return err
}
EOF

